"""Generate read-only, monochrome LCD glyphs from Cascadia Mono (SIL OFL).

Requires Pillow only when regenerating; firmware builds use the checked-in data.
"""

import argparse
import hashlib
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont


def generate(font_path, output):
    lines = [
        "// Generated by tools/generate_status_font.py; do not edit.",
        "// TI LCD Mono: derived from Cascadia Mono, Copyright Microsoft Corporation.",
        "// SPDX-License-Identifier: OFL-1.1",
        "// See ../fonts/OFL.txt. Glyphs use the SIL Open Font License, not Apache-2.0.",
        f"// Source font SHA-256: {hashlib.sha256(font_path.read_bytes()).hexdigest()}",
        "#pragma once", "#include <stdint.h>", "namespace StatusFont {",
    ]
    for name, size, width, height, baseline, characters in [
        ("Body", 15, 9, 18, 13, ''.join(chr(c) for c in range(32, 127))),
        ("Compact", 10, 7, 12, 9, ''.join(chr(c) for c in range(32, 127))),
        ("Large", 28, 16, 28, 22, "TI-LightONF"),
    ]:
        font = ImageFont.truetype(str(font_path), size)
        font.set_variation_by_axes([600])
        if name == "Large":
            lines.append(f'constexpr char kLargeCharacters[] = "{characters}";')
        lines.append(f"constexpr uint16_t k{name}[][{height}] = {{")
        for character in characters:
            image = Image.new("L", (width + 4, height + 4))
            ImageDraw.Draw(image).text((2, baseline + 2), character, font=font, fill=255, anchor="ls")
            pixels = image.load()
            rows = []
            for y in range(height + 4):
                for x in range(width + 4):
                    if pixels[x, y] >= 96:
                        assert 2 <= x < width + 2 and 2 <= y < height + 2, (name, character, x, y)
            for y in range(height):
                rows.append(sum(1 << x for x in range(width) if pixels[x + 2, y + 2] >= 96))
            lines.append("    { " + ", ".join(f"0x{row:04X}" for row in rows) + " },")
        lines.append("};")
    lines.append("} // namespace StatusFont")
    output.write_text("\n".join(lines) + "\n", encoding="ascii")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--font", type=Path, required=True)
    parser.add_argument("--output", type=Path, default=Path(__file__).resolve().parent.parent / "src/StatusFontData.h")
    args = parser.parse_args()
    generate(args.font, args.output)


if __name__ == "__main__":
    main()
